import java.util.HashMap;
import java.util.Scanner;

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    HashMap<Integer, Integer> colorPositions = new HashMap<>();
    int count = 0;

    for (int i = 0; i < 2 * n; i++) {
        int color = sc.nextInt();
        if (!colorPositions.containsKey(color)) {
            colorPositions.put(color, i);
        } else {
            int firstPosition = colorPositions.get(color);
            if (i - firstPosition == 2) {
                count++;
            }
        }
    }
    System.out.print(count);
}
